CREATE TABLE IF NOT EXISTS public.saved_images (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, storage_path TEXT NOT NULL, original_filename TEXT NOT NULL, file_size_bytes INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, model_used TEXT NOT NULL, processing_mode TEXT NOT NULL CHECK (processing_mode IN ('upscale', 'enhance', 'both', 'custom')), created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL, CONSTRAINT valid_file_size CHECK (file_size_bytes > 0), CONSTRAINT valid_width CHECK (width > 0), CONSTRAINT valid_height CHECK (height > 0));
